export const signedDistance=(p,f)=>{const dx=f.b.x-f.a.x,dy=f.b.y-f.a.y;return ((p.x-f.a.x)*dy-(p.y-f.a.y)*dx)/Math.hypot(dx,dy);};
export function panelsFor(folds){let panels=[[{x:0,y:0},{x:1,y:0},{x:1,y:1},{x:0,y:1}]];for(const f of folds){const next=[];for(const polygon of panels){const sides=[[],[]];for(let i=0;i<polygon.length;i++){const a=polygon[i],b=polygon[(i+1)%polygon.length],da=signedDistance(a,f),db=signedDistance(b,f);if(da>=-1e-9)sides[0].push(a);if(da<=1e-9)sides[1].push(a);if(da*db< -1e-18){const t=da/(da-db),q={x:a.x+(b.x-a.x)*t,y:a.y+(b.y-a.y)*t};sides[0].push(q);sides[1].push(q);}}for(const side of sides)if(side.length>=3){let area=0;for(let i=0;i<side.length;i++){const a=side[i],b=side[(i+1)%side.length];area+=a.x*b.y-b.x*a.y;}if(Math.abs(area)>1e-10)next.push(side);}}panels=next;}return panels;}
export function basisAt(p,folds,height){return [1,p.x-.5,p.y-.5,...folds.map(f=>Math.abs(signedDistance(p,f))*height)];}
export function pinBasis(pins,folds,height){const rows=[];for(const p of pins.length?pins:[{x:.5,y:0}]){const row=basisAt(p,folds,height);for(const q of rows){const dot=row.reduce((s,v,i)=>s+v*q[i],0);for(let i=0;i<row.length;i++)row[i]-=dot*q[i];}const length=Math.hypot(...row);if(length>1e-8)rows.push(row.map(v=>v/length));}return rows;}
export function constrainPins(coefficients,rows){const c=[...coefficients];for(const row of rows){const dot=c.reduce((s,v,i)=>s+v*row[i],0);for(let i=0;i<c.length;i++)c[i]-=dot*row[i];}return c;}
export const heightAt=(basis,coefficients)=>basis.reduce((s,v,i)=>s+v*coefficients[i],0);
function rotate(p,a,b,angle){const v=b.map((x,i)=>x-a[i]),l=Math.hypot(...v),k=v.map(x=>x/l),q=p.map((x,i)=>x-a[i]),c=Math.cos(angle),s=Math.sin(angle),dot=q.reduce((r,x,i)=>r+x*k[i],0),cross=[k[1]*q[2]-k[2]*q[1],k[2]*q[0]-k[0]*q[2],k[0]*q[1]-k[1]*q[0]];return q.map((x,i)=>a[i]+x*c+cross[i]*s+k[i]*dot*(1-c));}
export function rigidPose(vertices,folds,angles,width,height,pins){const world=p=>[(p.x-.5)*width,(.5-p.y)*height,0],axes=[];for(let j=0;j<folds.length;j++){const f=folds[j],positive=pins.filter(p=>signedDistance(p,f)>1e-6).length,negative=pins.filter(p=>signedDistance(p,f)<-1e-6).length,side=positive>negative?-1:1;let a=world(f.a),b=world(f.b);for(const previous of axes){if(signedDistance(f.a,previous.fold)*previous.side>1e-8)a=rotate(a,previous.a,previous.b,previous.angle);if(signedDistance(f.b,previous.fold)*previous.side>1e-8)b=rotate(b,previous.a,previous.b,previous.angle);}axes.push({a,b,fold:f,side,angle:positive&&negative?0:angles[j]*side});}return vertices.map(p=>{let q=world(p);for(const axis of axes)if(signedDistance(p,axis.fold)*axis.side>1e-8)q=rotate(q,axis.a,axis.b,axis.angle);return q;});}

